<template><view class="page"><view class="top"><text class="heading">校园约饭动态</text><button size="mini" :disabled="loading" @tap="load">刷新</button></view><text class="muted">展示同学真实发布的找人帖子，报名统一进入关联饭局审批。</text><view class="tabs"><text v-for="c in categories" :key="c" :class="{active:category===c}" @tap="category=c">{{c}}</text></view><view v-for="p in filtered" :key="p.id" class="card"><text class="author">{{p.author?.nickname||'同学'}}</text><text class="muted">{{p.category}} · {{timeText(p.createdAt)}}</text><text class="content">{{p.content}}</text><view class="venue" v-if="p.meal"><text>{{p.meal.title}}</text><text class="muted">{{p.meal.place}} · {{p.meal.currentPeople}}/{{p.meal.maxPeople}}人</text><button size="mini" @tap="open(p.mealId)">查看饭局 / 申请加入</button></view><text v-else class="muted">历史帖子没有关联饭局，仅供浏览。</text></view><text v-if="loading" class="muted">加载中…</text><text v-else-if="!filtered.length" class="muted">这里还没有真实帖子，可以从自己饭局的详情页发布到找人。</text><text class="error" v-if="error">{{error}}</text><button @tap="create">发起饭局</button></view></template>
<script>
import {request} from '../../services/api';import {localTime} from '../../services/time';
export default{data(){return {posts:[],category:'全部',loading:false,error:''}},computed:{categories(){return ['全部',...new Set(this.posts.map(p=>p.category).filter(Boolean))]},filtered(){return this.category==='全部'?this.posts:this.posts.filter(p=>p.category===this.category)}},onShow(){this.load()},methods:{timeText:localTime,async load(){if(this.loading)return;this.loading=true;this.error='';try{this.posts=(await request('/posts')).items;if(!this.categories.includes(this.category))this.category='全部'}catch(e){this.error=e.message||'加载失败，请重试'}finally{this.loading=false}},open(id){uni.navigateTo({url:'/pages/meal-detail/index?id='+id})},create(){uni.switchTab({url:'/pages/create-meal/index'})}}};
</script>
<style scoped>.page{padding:40rpx 32rpx}.top{display:flex;align-items:center;justify-content:space-between}.heading{font-size:40rpx;font-weight:800}.muted{display:block;font-size:25rpx;line-height:1.7;color:#888;margin:16rpx 0}.tabs{display:flex;gap:24rpx;flex-wrap:wrap;margin:24rpx 0}.active{border-bottom:6rpx solid #ffe388}.card{padding:28rpx 0;border-bottom:1px solid #eee}.author{display:block;font-weight:700}.content{display:block;white-space:pre-wrap;line-height:1.8}.venue{background:#faf7ef;border-radius:18rpx;padding:20rpx;margin:20rpx 0}.page button{background:#ffe388;border-radius:28rpx;margin:20rpx 0}.error{display:block;color:#b33}</style>
